/**
 * The ten animals of the evolution morph, generated by the motion study's authoring
 * script. Regenerate rather than hand-editing coordinates.
 *
 * Each animal is a back-to-front list of parts in the shared 200x160 box. Points are
 * "x y" control points of a smooth curve, and a trailing "*" marks a sharp corner.
 * Kinds: "solid" is a closed outline filled with the ground colour (it hides what is
 * behind it), "limb" an open outline with ground fill, "line" an open stroke, "ring" a
 * closed stroke, and "dot" a closed shape filled with ink (pupils, nostrils). An optional
 * third entry names the body part (body, head, fore-near, hind-far, …): parts with the same
 * role always morph into each other, so a limb never flies across to become another limb.
 */

export type PartKind = "solid" | "limb" | "line" | "ring" | "dot";

export type PartRole = "body" | "head" | "fore-near" | "fore-far" | "hind-near" | "hind-far";

export type AnimalDef = {
  key: string;
  name: string;
  parts: Array<[PartKind, string] | [PartKind, string, PartRole]>;
};

